-- Generated by scripts/generate-mythic-items.ps1 for the locked AzerothCore schema.
-- Custom item entries occupy 9,100,000 through 9,899,999.

CREATE TABLE IF NOT EXISTS `mod_mythic_rewards_variant` (
  `variant_id` tinyint unsigned NOT NULL,
  `item_level` smallint unsigned NOT NULL,
  PRIMARY KEY (`variant_id`),
  UNIQUE KEY `uk_item_level` (`item_level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

