CREATE TABLE IF NOT EXISTS `mod_mythic_rewards_source` (
  `map_id` smallint unsigned NOT NULL,
  `source_entry` int unsigned NOT NULL,
  PRIMARY KEY (`map_id`, `source_entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `mod_mythic_rewards_source`;
INSERT IGNORE INTO `mod_mythic_rewards_source` (`map_id`, `source_entry`)
SELECT loot.map_id, loot.item_entry FROM (
  SELECT loot_ids.map_id, l.Item AS item_entry
  FROM (
    SELECT DISTINCT c.map AS map_id, ct.lootid
    FROM creature c JOIN creature_template ct ON ct.entry = c.id
    WHERE c.map IN (574,575,576,578,599,600,601,602,604,619,632,658) AND ct.lootid > 0
    UNION
    SELECT DISTINCT c.map AS map_id, heroic.lootid
    FROM creature c JOIN creature_template ct ON ct.entry = c.id
    JOIN creature_template heroic ON heroic.entry = ct.difficulty_entry_1
    WHERE c.map IN (574,575,576,578,599,600,601,602,604,619,632,658) AND heroic.lootid > 0
  ) loot_ids JOIN creature_loot_template l ON l.Entry = loot_ids.lootid
  WHERE l.Item > 0
  UNION
  SELECT loot_ids.map_id, r.Item AS item_entry
  FROM (
    SELECT DISTINCT c.map AS map_id, ct.lootid
    FROM creature c JOIN creature_template ct ON ct.entry = c.id
    WHERE c.map IN (574,575,576,578,599,600,601,602,604,619,632,658) AND ct.lootid > 0
    UNION
    SELECT DISTINCT c.map AS map_id, heroic.lootid
    FROM creature c JOIN creature_template ct ON ct.entry = c.id
    JOIN creature_template heroic ON heroic.entry = ct.difficulty_entry_1
    WHERE c.map IN (574,575,576,578,599,600,601,602,604,619,632,658) AND heroic.lootid > 0
  ) loot_ids JOIN creature_loot_template l ON l.Entry = loot_ids.lootid
  JOIN reference_loot_template r ON r.Entry = l.Reference
  WHERE l.Reference > 0 AND r.Item > 0
) loot JOIN item_template src ON src.entry = loot.item_entry
WHERE src.Quality BETWEEN 3 AND 4 AND src.ItemLevel BETWEEN 175 AND 232
  AND src.RequiredLevel <= 80 AND src.InventoryType NOT IN (0,12)
  AND src.class IN (2,4) AND src.itemset = 0 AND src.startquest = 0;

DELETE FROM `item_template_locale` WHERE `ID` BETWEEN 9100000 AND 9899999;
DELETE FROM `item_template` WHERE `entry` BETWEEN 9100000 AND 9899999;

