INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`, `VerifiedBuild`)
SELECT 9000000 + (v.variant_id * 100000) + locale.ID, locale.locale,
  CONCAT(locale.Name, IF(locale.locale IN ('zhCN','zhTW'), ' [大秘境 ', ' [Mythic '), v.item_level, ']'),
  locale.Description, NULL
FROM `item_template_locale` locale
JOIN (SELECT DISTINCT `source_entry` FROM `mod_mythic_rewards_source`) source
  ON source.source_entry = locale.ID
CROSS JOIN `mod_mythic_rewards_variant` v;

CREATE TABLE IF NOT EXISTS `mod_mythic_rewards_item_pool` (
  `map_id` smallint unsigned NOT NULL,
  `variant_id` tinyint unsigned NOT NULL,
  `source_entry` int unsigned NOT NULL,
  `item_entry` int unsigned NOT NULL,
  PRIMARY KEY (`map_id`, `variant_id`, `source_entry`),
  KEY `idx_pool` (`map_id`, `variant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `mod_mythic_rewards_item_pool`;
INSERT INTO `mod_mythic_rewards_item_pool` (`map_id`, `variant_id`, `source_entry`, `item_entry`)
SELECT source.map_id, v.variant_id, source.source_entry,
  9000000 + (v.variant_id * 100000) + source.source_entry
FROM `mod_mythic_rewards_source` source CROSS JOIN `mod_mythic_rewards_variant` v;

